import{_ as o,h as n,i as e,c as l,v as t,p as s,x as i,m as p,e as h,S as L}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"ViT 作为视觉编码器","description":"","frontmatter":{"title":"ViT 作为视觉编码器","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vit-as-encoder.md","filePath":"llm/vit-as-encoder.md","lastUpdated":1788454257000}'),d={name:"llm/vit-as-encoder.md"};function c(m,a,E,V,P,T){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="vit-作为视觉编码器" tabindex="-1">ViT 作为视觉编码器 <a class="header-anchor" href="#vit-作为视觉编码器" aria-label="Permalink to &quot;ViT 作为视觉编码器&quot;">​</a></h1><div class="epigraph"><p>把图像切成固定大小的块、线性投射进 Transformer，视觉就可以和语言共用同一套注意力骨干；在足够数据上，归纳偏置可以从卷积换成大规模预训练。</p><footer>—— Alexey Dosovitskiy 等, ViT, 2020</footer></div><p>多模态模型里的「看」，今天几乎都是一个 Vision Transformer 把图变成 token 序列，再交给连接器与 LLM。Dosovitskiy 等人 2020 年的 ViT 把这套切块–嵌入–编码器写清楚；Radford 等人的 <a href="/llm/clip">CLIP</a> 再把它放进图文对比空间。接到 Vicuna、Qwen、InternLM 时，分类头被丢掉，留下的是 patch 隐状态。本篇讲 ViT 作为视觉编码器时哪些结构决定会变成 VLM 的瓶颈：切块粒度、分辨率、位置编码、以及输出哪些 token。投影方式见 <a href="/llm/llava-projector">LLaVA 投影器</a>，高分辨率切格见 <a href="/llm/anyres">AnyRes</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>卷积网络的归纳偏置适合自然照片的局部平移，但输出是特征图，接到自回归 LLM 还要再设计如何展平、如何对齐语言位置。ViT 的问题提法更硬：图像就是序列。一旦成立，视觉侧可以复用 Transformer 的缩放、残差与注意力实现，也可以直接在 patch 序列上做与文本同构的位置编码。代价是：切块把空间分辨率钉死在 \\(P\\times P\\) 的格子上，小于一块的字和边界会糊进同一个 token；输入分辨率若固定，高清图只能先被 squish。</p><p>VLM 还多一条约束：LLM 的上下文预算有限。视觉编码器吐出的 token 数 \\(\\approx HW/P^2\\)，会直接占满语言上下文。编码器设计不再只对 ImageNet 准确率负责，还要对「多少个视觉 token、每个 token 多细」负责。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="切块、线性嵌入与编码器" tabindex="-1">切块、线性嵌入与编码器 <a class="header-anchor" href="#切块、线性嵌入与编码器" aria-label="Permalink to &quot;切块、线性嵌入与编码器&quot;">​</a></h3><p>\\(H\\times W\\) 的图按 \\(P\\times P\\) 切开（经典配置 \\(P=16\\)，CLIP 常用 \\(P=14\\)），每块展平为 \\(P^2\\cdot C\\) 维，乘嵌入矩阵得到 \\(d\\) 维向量，再加位置编码，送入标准 Transformer 编码器。分类任务在序列前插 <code>[CLS]</code>；作为 VLM 编码器时，更常见的是把全部 patch 隐状态（有时加上 CLS）交给投影器，因为语言模型需要空间上铺开的证据，而不是一个全局向量。</p> \\[x_{i,j}=W\\,e_{i,j}+p_{i,j},\\qquad z=\\mathrm{Transformer}(x) \\]<p>其中 \\(e_{i,j}\\) 是格子 \\((i,j)\\) 的原始像素块。没有卷积下采样金字塔，空间结构全靠位置编码和注意力。预训练数据不够时，ViT 会弱于 ResNet；数据与算力够时，这条序列化路径成为默认。</p><p><span class="marginnote">\\(P\\) 是视觉侧最硬的超参。\\(P=32\\) 省 token、毁细字；\\(P=8\\) 保细节、把视觉序列拉到与一篇短文相当。VLM 里改 \\(P\\) 等于同时改 OCR 能力与 LLM 上下文占用，不能只抄分类论文的 16。</span></p><h3 id="分辨率与位置编码" tabindex="-1">分辨率与位置编码 <a class="header-anchor" href="#分辨率与位置编码" aria-label="Permalink to &quot;分辨率与位置编码&quot;">​</a></h3><p>ImageNet 式 ViT 用固定边长（如 224）加可学习一维位置嵌入。换分辨率必须插值位置嵌入，否则格子对不上。CLIP ViT 把常用边长抬到 224 或 336，仍然是固定画布：非方形图被 resize，文档被压扁。VLM 要高分辨率时有两条路：在固定 \\(P\\) 下增大 \\(H,W\\)（token 数平方涨），或把图切成多块分别过同一 ViT（<a href="/llm/anyres">AnyRes</a>），或按原生分辨率切块（<a href="/llm/qwen-vl-naive-dynamic-res">Qwen2-VL</a>）。后两条都要求位置编码能表达二维格子，而不是假设长度为常数。</p>',14)),(e(),s(L,null,{default:i(()=>[h(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20B%5B%22P%20%E4%B9%98%20P%20%E5%88%87%E5%9D%97%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%BA%BF%E6%80%A7%E5%B5%8C%E5%85%A5%E5%8A%A0%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20C%20--%3E%20D%5B%22Transformer%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20D%20--%3E%20E%5B%22patch%20%E9%9A%90%E7%8A%B6%E6%80%81%E5%BA%8F%E5%88%97%22%5D%0A%20%20E%20--%3E%20F%5B%22%E4%BA%A4%E7%BB%99%E6%8A%95%E5%BD%B1%E5%99%A8%E6%88%96%E8%BF%9E%E6%8E%A5%E5%99%A8%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="冻骨干还是端到端" tabindex="-1">冻骨干还是端到端 <a class="header-anchor" href="#冻骨干还是端到端" aria-label="Permalink to &quot;冻骨干还是端到端&quot;">​</a></h3><p>LLaVA 一类常冻 CLIP ViT，只训投影与 LLM，视觉几何几乎不变。InternVL 把 ViT 本身做成大规模视觉基础模型并参与对齐，编码器会为生成任务改写特征。冻骨干省算力、保留 CLIP 的开放词汇；解冻才能让细字、表格线、截图 UI 进入损失。选择应由任务定：自然图像字幕可以冻；文档 VLM 往往必须让 ViT 看见更高清的输入，并允许它更新。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ViT 能当视觉编码器，是因为它输出的已经是与 LLM 同构的 token 序列：同一套残差、同一套注意力混合。连接器不必把特征图「翻译成另一种计算」，只需做空间上的线性或浅 MLP 对齐。注意力在 patch 之间是全局的，一张图里任意两块理论上一步可达，这有利于「左上角标题与右下角合计」这类跨区域指代；也意味着复杂度随 patch 数二次，高分辨率会先打爆视觉编码器自己，而不只是 LLM。</p><p>位置编码决定模型是否知道块在哪。一维可学习 PE 把二维结构挤进一条序列顺序，对固定 raster 扫描够用；分辨率一变或切格顺序一变，就必须插值或改用二维 RoPE。VLM 的定位、OCR 读序，依赖的是「token 仍携带稳定的二维坐标」，不是 CLS 里的主题。</p><p><span class="marginnote">CLS 适合检索与对比学习的全局向量；生成式 VLM 若只把 CLS 投进 LLM，等于主动丢掉布局。LLaVA 保留 patch 序列是机制上的选择：让语言侧仍能做空间注意力。压缩视觉 token 时，删的是哪些 patch，等于删哪一块版面。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>固定画布会扭曲宽表、长截图、手机长图。切块不可逆：跨 patch 的细笔画被切开，要靠后续层拼回来，小字号 OCR 会先失败。视觉编码器的二次注意力在 4K 图上比 LLM 侧更早成为墙，于是才有窗口注意力、patch merge、像素 shuffle——那些是压缩与核，不是否定 ViT。</p><p>不要把「用了 ViT」理解成「用了 CLIP」。ImageNet ViT、CLIP ViT、SigLIP、InternViT 的监督不同，接到 LLM 的零样本起点不同。也不要把 patch 数当成免费的分辨率：AnyRes 多切几格，LLM 上下文线性涨，生成变慢，这是 <a href="/llm/vision-token-compression">视觉 token 压缩</a> 要管的账。</p><p><span class="marginnote">评测视觉编码器时，ImageNet 或 CLIP 检索高，不保证文档 VQA 高。应在目标分辨率、目标文字大小上直接测读字，而不是只报骨干论文的分类数。</span></p><p>取舍：默认用 CLIP 类 ViT 出 patch 序列；分辨率策略与是否解冻，按 OCR 与上下文预算联合选。切块大小一旦为了省 token 加大，后面的连接器补不回已经混进同一 patch 的笔画。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ViT 把图像切成 \\(P\\times P\\) 块，线性嵌入后用 Transformer 编成 patch token 序列，作为 VLM 的视觉前端。</li><li>VLM 通常丢分类头、保留空间上的 patch 隐状态，而不是只送 CLS。</li><li>分辨率、patch 大小与位置编码共同决定细字能否被看见、序列有多长。</li><li>固定画布会扭曲版式；高分辨率要靠切格、原生切块或更大输入，并接受 token 增长。</li><li>冻 CLIP 骨干省算力；文档与 UI 往往需要更高清输入并解冻编码器。</li><li>视觉侧自己也有二次注意力，高分辨率要另做窗口或合并，不能只催 LLM。</li><li>出处：Dosovitskiy et al., <em>An Image is Worth 16×16 Words</em>, 2020。对齐见 Radford et al., CLIP, 2021；接到 LLM 见 Liu et al., LLaVA, 2023。</li></ul>',13))])}const _=o(d,[["render",c]]);export{f as __pageData,_ as default};
